"use client"

import * as React from "react"
import { AlertCircle, Check, Copy, RotateCcw } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export type ChatRole = "user" | "assistant" | "system"
export type ChatMessageStatus = "sending" | "sent" | "error"
export type ChatMessageSide = "incoming" | "outgoing"
export type ChatMessageVariant = "default" | "note"
export type ChatMessageReceipt = "seen" | "unseen"

export type ChatMessageProps = {
  role: ChatRole
  children: React.ReactNode
  /** Shown above the bubble. Defaults to a role label. */
  name?: string
  /** Preformatted time. The host owns locale and timezone. */
  time?: string
  avatar?: React.ReactNode
  /** Overrides the side implied by `role`. Existing roles stay the same when this is omitted. */
  side?: ChatMessageSide
  /** `note` tints the bubble and labels it as an internal note. */
  variant?: ChatMessageVariant
  noteLabel?: string
  /** Seen state, shown under the bubble. Omitted when unset. */
  receipt?: ChatMessageReceipt
  seenLabel?: string
  unseenLabel?: string
  status?: ChatMessageStatus
  reactions?: readonly { emoji: string; count: number; mine?: boolean }[]
  onReact?: (emoji: string) => void
  /** Plain text passed to the copy action. Falls back to string children. */
  copyText?: string
  onRetry?: () => void
  onRegenerate?: () => void
  onCopy?: (text: string) => void
  sendingLabel?: string
  errorLabel?: string
  retryLabel?: string
  copyLabel?: string
  copiedLabel?: string
  regenerateLabel?: string
  className?: string
  bubbleClassName?: string
  actionsClassName?: string
}

const ROLE_LABEL: Record<ChatRole, string> = {
  user: "You",
  assistant: "Assistant",
  system: "System",
}

function textFromChildren(children: React.ReactNode): string {
  if (typeof children === "string" || typeof children === "number") return String(children)
  if (Array.isArray(children)) return children.map(textFromChildren).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(children)) {
    return textFromChildren(children.props.children)
  }
  return ""
}

function Initials({ name }: { name: string }) {
  const letters = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
  return (
    <span
      aria-hidden
      className="grid size-7 shrink-0 place-items-center rounded-full bg-muted text-[10px] font-medium text-muted-foreground"
    >
      {letters || "?"}
    </span>
  )
}

export function ChatMessage({
  role,
  children,
  name,
  time,
  avatar,
  side,
  variant = "default",
  noteLabel = "Internal note",
  receipt,
  seenLabel = "Seen",
  unseenLabel = "Not seen",
  status = "sent",
  reactions,
  onReact,
  copyText,
  onRetry,
  onRegenerate,
  onCopy,
  sendingLabel = "Sending",
  errorLabel = "Not sent",
  retryLabel = "Retry",
  copyLabel = "Copy",
  copiedLabel = "Copied",
  regenerateLabel = "Regenerate",
  className,
  bubbleClassName,
  actionsClassName,
}: ChatMessageProps) {
  const label = name ?? ROLE_LABEL[role]
  const [copied, setCopied] = React.useState(false)
  const copiedTimer = React.useRef<number>(0)
  const mine = side ? side === "outgoing" : role === "user"
  const system = role === "system"
  const note = variant === "note"

  React.useEffect(() => () => window.clearTimeout(copiedTimer.current), [])

  async function copy() {
    const text = copyText ?? textFromChildren(children)
    try {
      await navigator.clipboard.writeText(text)
      onCopy?.(text)
      setCopied(true)
      window.clearTimeout(copiedTimer.current)
      copiedTimer.current = window.setTimeout(() => setCopied(false), 1600)
    } catch {
      setCopied(false)
    }
  }

  const showActions = !system && status !== "sending" && (role === "assistant" || status === "error")

  return (
    <article
      data-slot="chat-message"
      data-role={role}
      data-side={mine ? "outgoing" : system ? "center" : "incoming"}
      data-variant={variant}
      data-status={status}
      data-receipt={receipt}
      aria-busy={status === "sending" || undefined}
      className={cn(
        "flex w-full gap-2",
        system && "justify-center",
        mine && "flex-row-reverse",
        className,
      )}
    >
      {system ? null : avatar ?? <Initials name={label} />}
      <div className={cn("flex min-w-0 max-w-[min(100%,36rem)] flex-col gap-1", mine && "items-end")}>
        {system ? null : (
          <div className={cn("flex items-baseline gap-2 px-1", mine && "flex-row-reverse")}>
            <span className="text-xs font-medium">{label}</span>
            {note ? (
              <span className="rounded-full bg-accent px-1.5 py-0.5 text-[10px] font-medium text-accent-foreground">
                {noteLabel}
              </span>
            ) : null}
            {time ? <time className="text-[11px] text-muted-foreground tabular-nums">{time}</time> : null}
          </div>
        )}
        <div
          className={cn(
            "rounded-2xl px-3 py-2 text-sm leading-relaxed wrap-break-word",
            system && "bg-transparent px-0 text-center text-xs text-muted-foreground",
            mine && !note && "rounded-ee-md bg-primary text-primary-foreground",
            !mine && !system && !note && "rounded-es-md bg-muted text-foreground",
            note && "border border-border bg-accent text-accent-foreground",
            status === "sending" && "opacity-70",
            status === "error" && "ring-1 ring-destructive/50",
            bubbleClassName,
          )}
        >
          {children}
        </div>
        {receipt && !system ? (
          <p className="px-1 text-[11px] text-muted-foreground" data-receipt={receipt}>
            {receipt === "seen" ? seenLabel : unseenLabel}
          </p>
        ) : null}
        {reactions?.length ? (
          <div className="flex flex-wrap gap-1 px-1">
            {reactions.map((reaction) => (
              <button
                key={reaction.emoji}
                type="button"
                aria-pressed={reaction.mine || undefined}
                aria-label={`${reaction.emoji}, ${reaction.count}`}
                className={cn(
                  "inline-flex items-center gap-1 rounded-full border border-border px-2 py-0.5 text-xs",
                  reaction.mine && "border-primary bg-primary/10",
                )}
                onClick={() => onReact?.(reaction.emoji)}
              >
                <span aria-hidden>{reaction.emoji}</span>
                <span className="tabular-nums">{reaction.count}</span>
                <span className="sr-only">{reaction.emoji}</span>
              </button>
            ))}
          </div>
        ) : null}
        {status === "sending" ? (
          <p className="px-1 text-[11px] text-muted-foreground">{sendingLabel}</p>
        ) : null}
        {status === "error" ? (
          <p className="flex items-center gap-1 px-1 text-[11px] text-destructive">
            <AlertCircle className="size-3" aria-hidden />
            {errorLabel}
          </p>
        ) : null}
        {showActions ? (
          <div className={cn("flex items-center gap-0.5", actionsClassName)}>
            {status === "error" && onRetry ? (
              <Button type="button" variant="ghost" size="xs" onClick={onRetry}>
                <RotateCcw />
                {retryLabel}
              </Button>
            ) : null}
            {role === "assistant" && status !== "error" ? (
              <>
                <Button type="button" variant="ghost" size="xs" onClick={() => void copy()} aria-label={copied ? copiedLabel : copyLabel}>
                  {copied ? <Check /> : <Copy />}
                  {copied ? copiedLabel : copyLabel}
                </Button>
                {onRegenerate ? (
                  <Button type="button" variant="ghost" size="xs" onClick={onRegenerate}>
                    <RotateCcw />
                    {regenerateLabel}
                  </Button>
                ) : null}
              </>
            ) : null}
          </div>
        ) : null}
      </div>
    </article>
  )
}

"use client"

import * as React from "react"
import { ChevronDown } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import { deskInitials, type DeskOption, type DeskPresence } from "@/lib/inbox"

export type ContactField = {
  id: string
  label: string
  value: string
  options?: readonly DeskOption[]
  onChange?: (value: string) => void
  readOnly?: boolean
}

export type ContactSection = {
  id: string
  title: string
  defaultOpen?: boolean
  content: React.ReactNode
}

export type ContactPanelClassNames = {
  root?: string
  tabs?: string
  card?: string
  section?: string
}

export type ContactPanelProps = {
  tab?: "details" | "copilot"
  defaultTab?: "details" | "copilot"
  onTabChange?: (tab: "details" | "copilot") => void
  detailsLabel?: string
  copilotLabel?: string
  contactName: string
  presence?: DeskPresence
  presenceLabel?: string
  viewContactLabel?: string
  onViewContact?: () => void
  fields?: readonly ContactField[]
  spamLabel?: string
  onMarkSpam?: () => void
  sections?: readonly ContactSection[]
  copilot?: React.ReactNode
  copilotEmpty?: string
  className?: string
  classNames?: ContactPanelClassNames
}

export function ContactPanel({
  tab: tabProp,
  defaultTab = "details",
  onTabChange,
  detailsLabel = "Details",
  copilotLabel = "Copilot",
  contactName,
  presence,
  presenceLabel,
  viewContactLabel = "View contact",
  onViewContact,
  fields = [],
  spamLabel = "Mark as spam",
  onMarkSpam,
  sections = [],
  copilot,
  copilotEmpty = "Nothing suggested yet.",
  className,
  classNames,
}: ContactPanelProps) {
  const [tabState, setTabState] = React.useState(defaultTab)
  const tab = tabProp ?? tabState
  const detailsId = React.useId()
  const copilotId = React.useId()
  const detailsTab = React.useId()
  const copilotTab = React.useId()

  function setTab(next: "details" | "copilot") {
    if (tabProp === undefined) setTabState(next)
    onTabChange?.(next)
  }

  function onTabKey(event: React.KeyboardEvent<HTMLButtonElement>) {
    if (event.key !== "ArrowRight" && event.key !== "ArrowLeft") return
    event.preventDefault()
    const next = tab === "details" ? "copilot" : "details"
    setTab(next)
    document.getElementById(next === "details" ? detailsTab : copilotTab)?.focus()
  }

  return (
    <aside
      data-slot="contact-panel"
      data-tab={tab}
      className={cn("flex min-h-0 min-w-0 flex-col bg-background", className, classNames?.root)}
    >
      <div role="tablist" aria-label={detailsLabel} className={cn("flex border-b border-border", classNames?.tabs)}>
        {(
          [
            { id: detailsTab, panel: detailsId, value: "details" as const, label: detailsLabel },
            { id: copilotTab, panel: copilotId, value: "copilot" as const, label: copilotLabel },
          ]
        ).map((item) => {
          const selected = tab === item.value
          return (
            <button
              key={item.value}
              id={item.id}
              type="button"
              role="tab"
              aria-selected={selected}
              aria-controls={item.panel}
              tabIndex={selected ? 0 : -1}
              className={cn(
                "flex-1 border-b-2 px-3 py-2 text-sm font-medium focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                selected ? "border-foreground text-foreground" : "border-transparent text-muted-foreground",
              )}
              onClick={() => setTab(item.value)}
              onKeyDown={onTabKey}
            >
              {item.label}
            </button>
          )
        })}
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto">
        <div id={detailsId} role="tabpanel" aria-labelledby={detailsTab} hidden={tab !== "details"} className="flex flex-col gap-4 p-3">
          <div className={cn("flex items-center gap-3", classNames?.card)}>
            <span className="relative grid size-10 shrink-0 place-items-center rounded-full bg-muted text-xs font-medium text-muted-foreground">
              <span aria-hidden>{deskInitials(contactName)}</span>
              {presence ? (
                <span
                  data-presence={presence}
                  className={cn(
                    "absolute end-0 bottom-0 size-2.5 rounded-full ring-2 ring-background",
                    presence === "online" && "bg-primary",
                    presence === "offline" && "bg-muted-foreground",
                    presence === "away" && "bg-accent-foreground",
                  )}
                />
              ) : null}
            </span>
            <span className="min-w-0">
              <span className="block truncate text-sm font-semibold">{contactName}</span>
              {presenceLabel ? <span className="block text-xs text-muted-foreground">{presenceLabel}</span> : null}
            </span>
          </div>
          {onViewContact ? (
            <Button type="button" variant="outline" size="sm" onClick={onViewContact}>
              {viewContactLabel}
            </Button>
          ) : null}
          <div className="grid gap-3">
            {fields.map((field) => (
              <label key={field.id} className="grid gap-1">
                <span className="text-xs text-muted-foreground">{field.label}</span>
                {field.options && !field.readOnly ? (
                  <select
                    aria-label={field.label}
                    value={field.value}
                    onChange={(event) => field.onChange?.(event.target.value)}
                    className="h-8 rounded-md border border-input bg-background px-2 text-sm focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                  >
                    {field.options.map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                ) : (
                  <span className="text-sm wrap-anywhere">{field.value || "—"}</span>
                )}
              </label>
            ))}
          </div>
          {onMarkSpam ? (
            <Button type="button" variant="outline" onClick={onMarkSpam}>
              {spamLabel}
            </Button>
          ) : null}
          {sections.length ? <Separator /> : null}
          {sections.map((section) => (
            <Collapsible key={section.id} defaultOpen={section.defaultOpen} className={classNames?.section}>
              <CollapsibleTrigger className="flex w-full items-center justify-between gap-2 py-1 text-left text-xs font-medium text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none">
                {section.title}
                <ChevronDown className="size-3.5" aria-hidden />
              </CollapsibleTrigger>
              <CollapsibleContent className="pt-2 text-sm">{section.content}</CollapsibleContent>
            </Collapsible>
          ))}
        </div>
        <div id={copilotId} role="tabpanel" aria-labelledby={copilotTab} hidden={tab !== "copilot"} className="flex flex-col gap-3 p-3">
          {copilot ?? <p className="text-sm text-muted-foreground">{copilotEmpty}</p>}
        </div>
      </div>
    </aside>
  )
}

"use client"

import * as React from "react"
import { ChevronDown, Inbox } from "lucide-react"
import { toast } from "sonner"

import { cn } from "@/lib/utils"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"

export type EntityFormProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description?: string
  presentation?: "dialog" | "sheet"
  onSubmit: (formData: FormData) => Promise<void> | void
  onDelete?: () => Promise<void> | void
  submitLabel?: string
  cancelLabel?: string
  deleteLabel?: string
  pendingLabel?: string
  /** Shown when onSubmit or onDelete rejects and onError is omitted. */
  errorLabel?: string
  onError?: (error: unknown) => void
  busy?: boolean
  children?: React.ReactNode
  className?: string
}

/**
 * Create or edit one record in a dialog or a sheet.
 *
 * Position is not part of the form. The parent should pass the existing
 * `position` through `keepPosition` so a save does not send the row to the end.
 * While `busy` is true (an upload, for example) submit stays disabled.
 */
export function EntityForm({
  open,
  onOpenChange,
  title,
  description,
  presentation = "dialog",
  onSubmit,
  onDelete,
  submitLabel = "Save",
  cancelLabel = "Cancel",
  deleteLabel = "Delete",
  pendingLabel = "Saving…",
  errorLabel = "Could not save",
  onError,
  busy = false,
  children,
  className,
}: EntityFormProps) {
  const [pending, setPending] = React.useState(false)
  const [confirmOpen, setConfirmOpen] = React.useState(false)
  const locked = busy || pending

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (locked) return
    const formData = new FormData(event.currentTarget)
    setPending(true)
    try {
      await onSubmit(formData)
      onOpenChange(false)
    } catch (error) {
      if (onError) onError(error)
      else toast.error(error instanceof Error && error.message ? error.message : errorLabel)
    } finally {
      setPending(false)
    }
  }

  const form = (
    <form className="flex min-h-0 flex-1 flex-col gap-4" onSubmit={handleSubmit}>
      <div className={cn("flex flex-col gap-3", className)}>{children}</div>
      <div className="mt-auto flex flex-wrap items-center gap-2">
        {onDelete ? (
          <Button type="button" variant="destructive" onClick={() => setConfirmOpen(true)} disabled={locked}>
            {deleteLabel}
          </Button>
        ) : null}
        <div className="ml-auto flex gap-2">
          <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={locked}>
            {cancelLabel}
          </Button>
          <Button type="submit" disabled={locked}>
            {pending ? pendingLabel : submitLabel}
          </Button>
        </div>
      </div>
    </form>
  )

  return (
    <>
      {presentation === "sheet" ? (
        <Sheet open={open} onOpenChange={onOpenChange}>
          <SheetContent className="flex w-full flex-col sm:max-w-md" side="right">
            <SheetHeader>
              <SheetTitle>{title}</SheetTitle>
              {description ? <SheetDescription>{description}</SheetDescription> : null}
            </SheetHeader>
            {form}
            <SheetFooter className="hidden" />
          </SheetContent>
        </Sheet>
      ) : (
        <Dialog open={open} onOpenChange={onOpenChange}>
          <DialogContent className="flex max-h-[85vh] flex-col sm:max-w-lg">
            <DialogHeader>
              <DialogTitle>{title}</DialogTitle>
              {description ? <DialogDescription>{description}</DialogDescription> : null}
            </DialogHeader>
            <div className="min-h-0 overflow-y-auto">{form}</div>
            <DialogFooter className="hidden" />
          </DialogContent>
        </Dialog>
      )}
      {onDelete ? (
        <ConfirmDelete
          open={confirmOpen}
          onOpenChange={setConfirmOpen}
          title={deleteLabel}
          description={description ?? title}
          confirmLabel={deleteLabel}
          cancelLabel={cancelLabel}
          errorLabel={errorLabel}
          onError={onError}
          onConfirm={async () => {
            await onDelete()
            setConfirmOpen(false)
            onOpenChange(false)
          }}
        />
      ) : null}
    </>
  )
}

export type ConfirmDeleteProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title?: string
  description?: string
  confirmLabel?: string
  cancelLabel?: string
  errorLabel?: string
  onError?: (error: unknown) => void
  onConfirm: () => Promise<void> | void
}

export function ConfirmDelete({
  open,
  onOpenChange,
  title = "Delete",
  description = "This cannot be undone.",
  confirmLabel = "Delete",
  cancelLabel = "Cancel",
  errorLabel = "Could not delete",
  onError,
  onConfirm,
}: ConfirmDeleteProps) {
  const [pending, setPending] = React.useState(false)
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>{cancelLabel}</AlertDialogCancel>
          <AlertDialogAction
            variant="destructive"
            disabled={pending}
            onClick={(event) => {
              event.preventDefault()
              setPending(true)
              void (async () => {
                try {
                  await onConfirm()
                } catch (error) {
                  if (onError) onError(error)
                  else toast.error(error instanceof Error && error.message ? error.message : errorLabel)
                } finally {
                  setPending(false)
                }
              })()
            }}
          >
            {confirmLabel}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

export function EmptyState({
  title,
  description,
  action,
  className,
}: {
  title: string
  description?: string
  action?: React.ReactNode
  className?: string
}) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-border px-6 py-10 text-center",
        className,
      )}
    >
      <Inbox className="size-5 text-muted-foreground" />
      <p className="text-sm font-medium">{title}</p>
      {description ? <p className="max-w-sm text-sm text-muted-foreground">{description}</p> : null}
      {action}
    </div>
  )
}

export function AdminSection({
  title,
  description,
  defaultOpen = true,
  children,
  className,
}: {
  title: string
  description?: string
  defaultOpen?: boolean
  children?: React.ReactNode
  className?: string
}) {
  return (
    <Collapsible defaultOpen={defaultOpen} className={cn("rounded-xl bg-card ring-1 ring-foreground/10", className)}>
      <CollapsibleTrigger className="flex w-full items-center gap-2 px-4 py-3 text-left">
        <span className="min-w-0 flex-1">
          <span className="block text-sm font-medium">{title}</span>
          {description ? <span className="block text-xs text-muted-foreground">{description}</span> : null}
        </span>
        <ChevronDown className="size-4 text-muted-foreground transition-transform in-data-[state=open]:rotate-180 motion-reduce:transition-none" />
      </CollapsibleTrigger>
      <CollapsibleContent className="flex flex-col gap-3 px-4 pb-4">{children}</CollapsibleContent>
    </Collapsible>
  )
}

"use client"

import * as React from "react"
import { Inbox, Search } from "lucide-react"

import { cn } from "@/lib/utils"
import { Input } from "@/components/ui/input"
import { deskInitials, foldInboxText, type DeskPresence } from "@/lib/inbox"

export type InboxRow = {
  id: string
  title: string
  subtitle?: string
  preview?: string
  time?: string
  unread?: number
  presence?: DeskPresence
  meta?: React.ReactNode
}

export type InboxListClassNames = {
  root?: string
  header?: string
  search?: string
  list?: string
  item?: string
  empty?: string
}

export type InboxListProps = {
  label: string
  title?: string
  countLabel?: string
  query?: string
  defaultQuery?: string
  onQueryChange?: (query: string) => void
  searchLabel?: string
  toolbar?: React.ReactNode
  items: readonly InboxRow[]
  selectedId?: string | null
  defaultSelectedId?: string | null
  onSelect?: (id: string) => void
  emptyTitle?: string
  emptyDescription?: string
  className?: string
  classNames?: InboxListClassNames
}

function sameRow(row: InboxRow, query: string) {
  if (!query.trim()) return true
  const hay = foldInboxText([row.title, row.subtitle, row.preview].filter(Boolean).join(" "))
  return hay.includes(foldInboxText(query))
}

export function InboxList({
  label,
  title,
  countLabel,
  query: queryProp,
  defaultQuery = "",
  onQueryChange,
  searchLabel = "Search",
  toolbar,
  items,
  selectedId: selectedProp,
  defaultSelectedId = null,
  onSelect,
  emptyTitle = "Nothing here",
  emptyDescription,
  className,
  classNames,
}: InboxListProps) {
  const listId = React.useId()
  const [queryState, setQueryState] = React.useState(defaultQuery)
  const [selectedState, setSelectedState] = React.useState<string | null>(defaultSelectedId)
  const query = queryProp ?? queryState
  const selectedId = selectedProp !== undefined ? selectedProp : selectedState
  const visible = items.filter((item) => sameRow(item, query))

  function setQuery(next: string) {
    if (queryProp === undefined) setQueryState(next)
    onQueryChange?.(next)
  }

  function select(id: string) {
    if (selectedProp === undefined) setSelectedState(id)
    onSelect?.(id)
  }

  function onListKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (!visible.length) return
    const index = Math.max(0, visible.findIndex((item) => item.id === selectedId))
    const last = visible.length - 1
    const nextIndex =
      event.key === "ArrowDown"
        ? Math.min(last, index + 1)
        : event.key === "ArrowUp"
          ? Math.max(0, index - 1)
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : -1
    if (nextIndex < 0 || !visible[nextIndex]) return
    event.preventDefault()
    select(visible[nextIndex].id)
    document.getElementById(`${listId}-${visible[nextIndex].id}`)?.focus()
  }

  return (
    <section
      data-slot="inbox-list"
      aria-label={label}
      className={cn("flex min-h-0 min-w-0 flex-col bg-background", className, classNames?.root)}
    >
      <header className={cn("flex flex-col gap-2 border-b border-border p-3", classNames?.header)}>
        {title || countLabel ? (
          <div className="flex items-baseline justify-between gap-2">
            {title ? <h2 className="truncate text-sm font-semibold">{title}</h2> : <span />}
            {countLabel ? <p className="shrink-0 text-xs text-muted-foreground tabular-nums">{countLabel}</p> : null}
          </div>
        ) : null}
        <div className="flex items-center gap-2">
          <div className={cn("relative min-w-0 flex-1", classNames?.search)}>
            <Search className="pointer-events-none absolute top-1/2 left-2 size-3.5 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder={searchLabel}
              aria-label={searchLabel}
              className="h-8 pl-7"
            />
          </div>
          {toolbar}
        </div>
      </header>
      {visible.length === 0 ? (
        <div className={cn("flex flex-1 flex-col items-center justify-center gap-2 px-6 py-10 text-center", classNames?.empty)} role="status">
          <Inbox className="size-5 text-muted-foreground" aria-hidden />
          <p className="text-sm font-medium wrap-anywhere">{emptyTitle}</p>
          {emptyDescription ? <p className="text-xs text-muted-foreground wrap-anywhere">{emptyDescription}</p> : null}
        </div>
      ) : (
        <div
          role="listbox"
          aria-label={label}
          aria-activedescendant={selectedId ? `${listId}-${selectedId}` : undefined}
          className={cn("flex min-h-0 flex-1 flex-col overflow-y-auto", classNames?.list)}
          onKeyDown={onListKeyDown}
        >
          {visible.map((item) => {
            const selected = item.id === selectedId
            return (
              <button
                key={item.id}
                id={`${listId}-${item.id}`}
                type="button"
                role="option"
                aria-selected={selected}
                tabIndex={selected || (!selectedId && item === visible[0]) ? 0 : -1}
                className={cn(
                  "flex w-full min-w-0 gap-2 border-b border-border px-3 py-2.5 text-left focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                  selected ? "bg-muted" : "hover:bg-muted/60",
                  classNames?.item,
                )}
                onClick={() => select(item.id)}
              >
                <PresenceMark name={item.title} presence={item.presence} />
                <span className="min-w-0 flex-1">
                  <span className="flex items-baseline gap-2">
                    <span className={cn("truncate text-sm", item.unread ? "font-semibold" : "font-medium")}>{item.title}</span>
                    {item.time ? <time className="ml-auto shrink-0 text-[11px] text-muted-foreground tabular-nums">{item.time}</time> : null}
                  </span>
                  {item.subtitle ? <span className="mt-0.5 block truncate text-xs text-muted-foreground">{item.subtitle}</span> : null}
                  {item.preview ? <span className="mt-0.5 block truncate text-xs text-muted-foreground">{item.preview}</span> : null}
                  {item.meta ? <span className="mt-1.5 flex min-w-0 flex-wrap items-center gap-1.5">{item.meta}</span> : null}
                </span>
                {item.unread ? (
                  <span className="mt-0.5 grid h-5 min-w-5 place-items-center rounded-full bg-primary px-1 text-[10px] font-medium text-primary-foreground tabular-nums">
                    <span className="sr-only">{item.unread} unread</span>
                    <span aria-hidden>{item.unread}</span>
                  </span>
                ) : null}
              </button>
            )
          })}
        </div>
      )}
    </section>
  )
}

export function PresenceMark({ name, presence }: { name: string; presence?: DeskPresence }) {
  return (
    <span className="relative mt-0.5 grid size-8 shrink-0 place-items-center rounded-full bg-muted text-[10px] font-medium text-muted-foreground">
      <span aria-hidden>{deskInitials(name)}</span>
      {presence ? (
        <span className="sr-only">{presence}</span>
      ) : null}
      {presence ? (
        <span
          data-presence={presence}
          className={cn(
            "absolute end-0 bottom-0 size-2 rounded-full ring-2 ring-background",
            presence === "online" && "bg-primary",
            presence === "offline" && "bg-muted-foreground",
            presence === "away" && "bg-accent-foreground",
          )}
        />
      ) : null}
    </span>
  )
}

